(async () => {
  let selectedRecords = this.getValue("item_array");
  const rowIndex = this.getParamsVariables("index");
  let updatedList = [];
  const tabPriceHistoryElement = document.getElementById(
    "tab-tab_price_history",
  );
  const tabPriceHistoryElement2 = document.getElementById(
    "tab-tab_price_history_2",
  );
  const tabPriceHistoryElement3 = document.getElementById(
    "tab-tab_price_book",
  );
  const tabPriceHistoryElement4 = document.getElementById(
    "tab-tab_multi_pricing",
  );
  console.log("tabPriceHistoryElement", tabPriceHistoryElement);
  const activeTab = tabPriceHistoryElement?.classList.contains("is-active")
    ? "SO"
    : tabPriceHistoryElement2?.classList.contains("is-active")
      ? "SI"
      : tabPriceHistoryElement3?.classList.contains("is-active")
      ? "PB"
      : tabPriceHistoryElement4?.classList.contains("is-active")
        ? "MP"
        : "IB";

  if (activeTab === "SO") {
    updatedList = this.getComponent("so_item_table").$refs.crud.updatelist;
  } else if (activeTab === "SI") {
    updatedList = this.getComponent("so_item_table_1").$refs.crud.updatelist;
  } else if (activeTab === "PB") {
    updatedList = this.getComponent("price_tag_table").$refs.crud.updatelist;
  }
  console.log("updatedList", updatedList);

  if (activeTab === "MP") {
  const selectedOption = this.getValue("select_price");

  const selectedValue =
    selectedOption && typeof selectedOption === "object"
      ? selectedOption.value
      : selectedOption;

  console.log("selectedOption", selectedOption);
  console.log("selectedValue", selectedValue);

  if (!selectedValue) {
    this.$message.warning("Please select a sales price.");
    return;
  }

  const selectedPrice = this.getValue(
    `sales_price_${selectedValue}`,
  );

  console.log("selectedPrice", selectedPrice);

  if (
    selectedPrice === null ||
    selectedPrice === undefined ||
    selectedPrice === ""
  ) {
    this.$message.warning("The selected sales price is empty.");
    return;
  }

  this.parentGenerateForm.triggerEvent(
    "onConfirm_applyLinePriceHistory",
    {
      selectedRecords: [
        {
          so_item_price: selectedPrice,
        },
      ],
      rowIndex,
      documentType: "MP",
    },
  );

  this.parentGenerateForm.$refs.SuPageDialogRef.hide();
  return;
}

  const latestSelectedRecords = selectedRecords.map((record) => {
    const editedLine = updatedList.find((item) => item.id === record.id);

    if(activeTab === "PB") {
      return {
        so_item_price: record.cust_price_unit_price,
      }
    }

    if (editedLine) {
      return {
        ...record,
        so_item_price: editedLine.so_item_price || record.so_item_price,
        so_quantity: editedLine.so_quantity || record.so_quantity,
      };
    } else {
      return { ...record };
    }
  });

  console.log("latestSelectedRecords", latestSelectedRecords);

  this.parentGenerateForm.triggerEvent("onConfirm_applyLinePriceHistory", {
    selectedRecords: latestSelectedRecords,
    rowIndex: rowIndex,
    documentType: activeTab,
  });
  this.parentGenerateForm.$refs.SuPageDialogRef.hide();
})();

